names = ["Ali", "Hina", "Sara", "Bilal", "Zara"]
grades = [80, 85, None, 78, 85]  # None = grade missing

known = [g for g in grades if g is not None]
average = sum(known) / len(known)

for name, grade in zip(names, grades):
    if grade is None:
        print(name, ":", round(average, 1), " <- missing, filled with class average")
    else:
        print(name, ":", grade)
